module adder_16bit
  (
   input [15:0] A,
   input [15:0] B,
   input Cin,
   output [15:0] S,
   output Cout
   );
   wire [16:0] c;

   adder_8 adder1 (
      .A(A[7:0]),
      .B(B[7:0]),
      .Cin(Cin),
      .S(S[7:0]),
      .Cout(c[8])
   );

   adder_8 adder2 (
      .A(A[15:8]),
      .B(B[15:8]),
      .Cin(c[8]),
      .S(S[15:8]),
      .Cout(c[16])
   );

   assign Cout = c[16];
endmodule
